<?php if(!defined('SW_APP')||!SW_PUBLIC){http_response_code(404);exit;} $rows=all('SELECT r.title,w.winning_number,w.claim_status FROM winners w JOIN participants p ON p.id=w.participant_id AND p.raffle_id=w.raffle_id JOIN raffles r ON r.id=w.raffle_id WHERE p.user_id=?',[$u['id']]); ?>
<p class="user-sub">Consulta los premios asociados a tus boletos.</p><?php if(!$rows):?><div class="user-empty">No hay premios registrados a tu nombre.</div><?php else:?><div class="user-table"><table><thead><tr><th>Sorteo</th><th>Número</th><th>Reclamo</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['winning_number'])?></td><td><?=h($r['claim_status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
